import { NextRequest, NextResponse } from 'next/server';

const allowedChecks = new Set(['live', 'ready']);

export async function GET(
  request: NextRequest,
  context: { params: Promise<{ check: string }> },
) {
  const { check } = await context.params;
  if (!allowedChecks.has(check)) {
    return NextResponse.json({ message: 'Not found.' }, { status: 404 });
  }

  const apiUrl = process.env.API_INTERNAL_URL ?? process.env.NEXT_PUBLIC_API_URL;
  if (!apiUrl) {
    return NextResponse.json({ message: 'Backend URL is not configured.' }, { status: 503 });
  }

  try {
    const upstream = await fetch(new URL(`/api/v1/health/${check}`, apiUrl), {
      cache: 'no-store',
      signal: AbortSignal.timeout(8000),
    });
    const body = await upstream.json();
    return NextResponse.json(body, { status: upstream.status });
  } catch {
    return NextResponse.json(
      { status: 'error', message: 'Backend health check is unavailable.' },
      { status: 502 },
    );
  }
}